insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 1, 'What does a load case generator return?', '["A single differential pressure at the casing shoe.", "Four arrays of equal length: a depth, the pressure inside, the pressure outside and the axial force.", "A pressure profile and a design factor set, from which the section verdicts are produced without any further calculation.", "Three arrays and a scalar, the scalar being the governing depth at which the section should be evaluated for that case."]'::jsonb, 1, 'Everything else in the tier is comparisons between those arrays and the ratings from the tier below.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 2, 'Why does the engine carry both pressure columns rather than their difference?', '["Because burst and collapse have opposite sign conventions.", "Because the two columns are measured independently in the field, and combining them early would lose the ability to audit them.", "Because the axial profile is computed from the internal column, so the inside pressure has to survive to the end of the routine.", "Because the triaxial check needs them separately: the Lame wall stresses depend on each one, not only on the difference."]'::jsonb, 3, 'A pipe with 60 MPa in and 30 out is not in the same state as one with 30 in and zero out.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 3, 'The published run puts 51 depths from surface to a shoe at 2507.919699301 m. What is the spacing?', '["50.15839398602 m, which is the shoe depth divided by the 50 intervals the grid uses.", "Fifty metres exactly, by construction.", "About 49.17 m, because the grid runs from the first point below surface to the shoe rather than from surface itself.", "It varies, because the grid is refined near the section boundaries where the pressure profiles are most likely to change slope."]'::jsonb, 0, 'The governing depth reported is therefore the worst SAMPLED depth rather than the worst depth.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 4, 'Why is every pressure in every load case computed on true vertical depth?', '["Because the ratings are also quoted per vertical metre.", "Because the grid is uniform, and a uniform grid in measured depth would give unequal vertical spacings on a deviated well.", "Because each column is a hydrostatic one, and hydrostatic pressure depends on vertical height rather than on path length.", "Because the axial force is the buoyed weight below each point, and weight also acts vertically rather than along the hole."]'::jsonb, 2, 'The measured depth matters for how much steel is hanging, and the engine takes the string weight as an input instead.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 5, 'At any one depth in one load case, how many of burst and collapse can be positive?', '["Both, whenever the two columns are of different densities.", "At most one, because they are the same subtraction with opposite signs.", "Both, since the burst check uses the inside pressure alone while the collapse check uses the outside pressure alone.", "Neither, unless the case was built specifically to load one of the two, which the naming convention makes explicit."]'::jsonb, 1, 'The engine tests each for positivity and skips the check when it is not.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 6, 'A section reports a burst safety factor of infinity and a governing depth of null. What does that mean?', '["That no depth in the section had a positive burst differential, so this case does not load it in burst at all.", "That the calculation failed and the result is missing.", "That the section''s burst rating exceeded the differential everywhere by more than the numerical precision could represent.", "That the section lies entirely above the point at which the two pressure columns cross, where the differential changes sign."]'::jsonb, 0, 'It is a real and useful answer rather than a missing number.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 7, 'A case named fullEvacuationCollapse also produces a burst number sometimes. Why is that allowed?', '["It is not allowed, and the engine suppresses it.", "Because the burst differential can turn positive above the fluid level, where the outside column has not yet built up any head.", "Because the naming convention is advisory only, and the engine has no way to associate a case name with a particular check.", "Because the name describes what the case was built to load, and the engine computes all four checks regardless."]'::jsonb, 3, 'The naming is a description of intent rather than a filter, and that matters once in module five.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 8, 'What sets the slope of the burst differential with depth?', '["The ratio of the two fluid densities involved.", "The design factor applied to burst, which scales the differential before it is compared with the rating for the section.", "The inside gradient less the outside gradient, so a lighter inside column makes the differential shrink downward.", "The buoyancy factor, since the axial profile and the pressure profile are both computed from the same mud density."]'::jsonb, 2, 'Every governing-depth result in the next module is that one line.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 9, 'Which column in the published environment has a gradient of only 2300 Pa per metre?', '["The seawater backup outside the pipe on the burst cases.", "The gas column inside the pipe on the kick case, which is nearly flat compared with any liquid.", "The displacement water inside the pipe during the cement job, which is the lightest of the liquid columns in the suite.", "The packer fluid below the level on the partial evacuation case, which is deliberately lighter than the mud outside."]'::jsonb, 1, 'Seawater is 10100.8495 and mud is 14121.576 by comparison.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 10, 'What does a section object carry?', '["A depth range, a diameter, a wall, a yield strength and a connection efficiency, which is one uniform piece of pipe.", "A grade name and a nominal weight from the catalog.", "A depth range and a set of four precomputed ratings, so that the load case evaluation does not repeat the rating formulas.", "A depth range and a reference to a catalog row, which the evaluation dereferences to recover the geometry it needs."]'::jsonb, 0, 'A string is a list of them, and this course''s published string has two.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 11, 'The published section break is at 1473.759701091 m. Which grid points bracket it?', '["Index 28 and index 29, which straddle the break exactly.", "None, because the grid is constructed to include every section boundary in addition to the fifty uniform intervals.", "Index 29 at 1454.59342559458 m and index 30 at 1504.7518195805999 m, so the break itself is not sampled.", "Index 29 and index 30, and the evaluation interpolates between them to recover the exact value at the boundary depth."]'::jsonb, 2, 'Neither section is evaluated exactly at the break, and on this string that costs a fraction of a percent.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 12, 'When would the grid missing the section boundary NOT be acceptable?', '["Whenever the section is shorter than the grid spacing.", "On any case where the burst differential is negative, because the check then skips the boundary point and reports a null.", "On a case with an internal fluid level, because the level introduces a discontinuity in the inside pressure column.", "On a profile with a kink at the boundary, which is what a change of fluid at a casing shoe produces."]'::jsonb, 3, 'On this string every profile is monotone inside each section and the governing point is an endpoint.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 13, 'Which of the seven cases has no pressure differential anywhere?', '["The cementing case, where the columns are balanced.", "The running case, because the pipe is full of mud and surrounded by the same mud.", "The custom gradient case, because its two densities are supplied by the user and default to the same mud weight if omitted.", "The partial evacuation case above the fluid level, where the inside pressure and the outside pressure are both zero."]'::jsonb, 1, 'What it has instead is the full buoyed weight plus any overpull applied at surface.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 14, 'What is the gas kick shoe pressure in the published run built from?', '["A fracture equivalent mud weight of 1800 kg/m3 at the shoe, times gravity times the shoe depth.", "A reservoir pressure supplied in the environment object.", "Twelve tenths of the mud hydrostatic at the shoe, which is the fallback the engine uses when nothing better is supplied.", "The maximum anticipated surface pressure plus the gas column weight, worked upward from the wellhead rather than downward."]'::jsonb, 0, 'That is the third of three ways the engine can set it, and it is the one this environment selects.'),
  ('casingtubing', 'intermediate', 'module', 'm01-a-load-case-is-two-columns', 15, 'The custom gradient case exists for what purpose?', '["To reproduce the published goldens exactly.", "To provide a baseline with no differential, against which the other six cases can be compared for their incremental effect.", "As an escape hatch: two densities and a surface pressure will build any case the other six do not cover.", "To model the annulus pressure that builds during production, which none of the six drilling cases represents at all."]'::jsonb, 2, 'The published run uses 500 kg/m3 inside with 5000000 Pa at surface against 1600 kg/m3 outside.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 1, 'In the gas kick case, what is inside the casing and what is behind it?', '["Mud inside and cement outside, as during displacement.", "Gas from the shoe up to surface inside, and a seawater backup column in the annulus outside.", "Gas inside and nothing outside, since the annulus is assumed empty in order to make the case as severe as it can be.", "Reservoir fluid inside up to the fracture depth and formation water outside, both taken at their in situ densities."]'::jsonb, 1, 'Calling it seawater is a convention for a conservative low density backup.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 2, 'Why does the gas kick design philosophy use the shoe fracture pressure?', '["Because the fracture pressure is easier to measure.", "Because the casing is designed to survive the pressure test, and the shoe fracture pressure is what the test is performed to.", "Because the shoe is the deepest point of the string, so the pressure there sets the internal column everywhere above it.", "Because anything worse would break the formation down rather than the pipe, so it bounds the credible load."]'::jsonb, 3, 'The casing is designed for the worst pressure the shoe can hold.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 3, 'The published gas column loses under 6 MPa over two and a half kilometres. What follows?', '["The internal pressure at surface is nearly the shoe pressure, while the external help has gone to zero there.", "The column can be treated as a single constant pressure.", "The burst differential is nearly constant with depth, since both columns lose a similar amount of head over the same interval.", "The gas gradient can be neglected entirely, which is what the engine does when no gas gradient is supplied in the environment."]'::jsonb, 0, 'That is the whole mechanism behind the governing depth being the wellhead.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 4, 'What is the slope of the gas kick burst differential on the published run?', '["Plus 4020.726499999999 Pa per metre, growing downward.", "Minus 2300 Pa per metre, which is the gas gradient itself, since the external column contributes nothing above the mud line.", "Minus 7800.8495 Pa per metre, the gas gradient less the seawater one.", "It is not constant, because the gas column is compressible and its density rises with the pressure at depth in the hole."]'::jsonb, 2, 'Negative, so the differential shrinks as you go down.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 5, 'On the published string, where does the gas kick govern section 1?', '["At the section shoe, 1473.759701091 m.", "At zero metres of true vertical depth, which is the wellhead itself.", "At the last grid point inside the section, 1454.59342559458 m, which is where every other case on that section governs.", "At the point where the two pressure columns cross, which on the published environment falls inside the upper section."]'::jsonb, 1, 'Not the shoe, not the casing seat, the christmas tree.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 6, 'Why is a gas kick governing at surface counterintuitive?', '["Because everything else about a well gets worse with depth, so the instinct is to check the bottom.", "Because gas is lighter than the fluid it displaces.", "Because the wellhead is the part of the system with the most steel around it and therefore the highest apparent capacity.", "Because the burst rating of the upper section is usually higher, which makes a low safety factor there look implausible."]'::jsonb, 0, 'It is the exception, and the reason is that the thing pushing outward is nearly weightless.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 7, 'Which design consequence follows from the gas kick governing at surface?', '["The shoe must be set shallower than the fracture depth.", "The annulus must be kept full of a heavy fluid, since the external column is what limits the differential at the wellhead.", "The surface section is often a higher grade than the section below it, which is exactly what the published string does.", "Wellhead equipment and the top joints are rated for the full shut-in surface pressure."]'::jsonb, 3, 'The published string is P-110 on top and L-80 below for that reason.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 8, 'In the pressure test case, what is the inside column?', '["A gas column from the shoe control pressure upward.", "The test pressure alone, applied uniformly along the string, since the mud is assumed compressible and transmits it equally.", "The test pressure applied at surface plus the mud hydrostatic below it.", "The mud hydrostatic alone, with the test pressure treated as an external load applied at the wellhead by the pump."]'::jsonb, 2, 'Mud at 1440 kg/m3 gives 14121.576 Pa per metre on top of the 35000000 Pa at surface.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 9, 'What is the slope of the pressure test burst differential?', '["Minus 7800.8495 Pa per metre, as the gas kick does.", "Plus 4020.726499999999 Pa per metre, so the case governs at the bottom of each section.", "Plus 14121.576 Pa per metre, which is the mud gradient, since the seawater backup is neglected in the burst calculation.", "Zero, because the test pressure is applied to the whole string at once and both columns are liquids of similar density."]'::jsonb, 1, 'Two liquid columns nearly cancel, which is why the slope is much gentler than the kick''s.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 10, 'Which of the two burst cases is worse on the published string?', '["The pressure test, on both sections, and by a wide margin on the lower one.", "The gas kick, on both sections.", "The gas kick on the upper section and the pressure test on the lower one, because the governing depths are at opposite ends.", "Neither, because their safety factors differ by less than the precision the design factors are quoted to."]'::jsonb, 0, 'It is also the only case in the whole suite that produces a non-passing verdict.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 11, 'Why should a test pressure not exceed the worst service load by a wide margin?', '["Because the test pressure is limited by the wellhead rating.", "Because the burst design factor of 1.1 is defined against the service load rather than against the test, so the margin is lost.", "Because a test is itself a load event the string has to survive, and the excess buys nothing.", "Because a higher test pressure raises the triaxial number as well, and triaxial has the tightest design factor of the four."]'::jsonb, 2, 'The test pressure is chosen by an engineer and the kick pressure is chosen by the formation.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 12, 'Every governing depth in this course is at an end of a section. Why?', '["Because the grid does not sample the section interiors.", "Because every differential is linear or piecewise linear in depth, and a linear function extremes at its endpoints.", "Because the evaluation loop only tests the first and last grid point inside each section, for reasons of computational cost.", "Because the ratings are constant within a section, so the extreme of the safety factor follows the extreme of the load exactly."]'::jsonb, 1, 'Every column in every case is a constant density hydrostatic.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 13, 'Which of the seven cases has a differential that is piecewise linear rather than linear?', '["Partial evacuation, because the inside gradient is zero above the fluid level and 11277.6475 below it.", "The gas kick, because the gas column is floored at zero.", "The cementing case, because the cement column is placed in two stages with a lead and a tail slurry of different densities.", "The running case, because the overpull is applied at surface and therefore only affects the upper part of the string."]'::jsonb, 0, 'Its extremes are at three candidate points rather than two, and one of them is inside the interval.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 14, 'A shoe-only burst check on the published gas kick gives 2.396900745393525 for section 1. What is the scanned answer?', '["The same number, since the section bottom governs.", "A slightly lower number, because the scan finds the worst of fifty one points rather than one and the profile is nearly flat.", "1.6904923854809817, which is the value at the wellhead, and the ratio between the two answers is 1.417871364567877.", "1.6904923854809817, so the simpler check overstates the margin by 41.8 percent."]'::jsonb, 3, 'A design factor of 1.1 does not survive an error of that size.'),
  ('casingtubing', 'intermediate', 'module', 'm02-the-burst-cases', 15, 'On which case does a shoe-only burst check give exactly the right answer?', '["The gas kick, once the annulus column is included.", "None of the seven, because the section bottom is never a grid point and the check therefore always evaluates the wrong depth.", "The pressure test, because the bottom of each section is where that case governs anyway.", "The running case, because it has no pressure differential and both methods correctly report an infinite safety factor."]'::jsonb, 2, 'That is the trap: the tool gives the right answer on most cases and the wrong one where it matters.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 1, 'In a full evacuation, what is the collapse differential equal to?', '["The difference between the mud and the packer fluid.", "The mud hydrostatic itself, because the inside pressure is zero at every depth in the string.", "The mud hydrostatic less the pore pressure of the formation opposite, since that is what supports the pipe from outside.", "The mud hydrostatic less the residual gas pressure left inside the string, which the engine takes as one atmosphere."]'::jsonb, 1, 'At the published shoe that comes to 35415778.63557866 Pa.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 2, 'Why is a full evacuation a credible case rather than a worst-case invention?', '["Because every well is evacuated during completion.", "Because the design factor for collapse is 1.0, which only makes sense if the case represents a real rather than a bounding load.", "Because a lost circulation zone below the shoe can swallow the fluid, which is a routine event on many wells.", "Because a lost circulation zone, a drillstem test or a gas lift unloading can all empty a string in practice."]'::jsonb, 3, 'It is also the standard assumption when nobody can prove the level will not fall.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 3, 'The collapse design factor in the published set is 1.0. What is the argument for it?', '["That the collapse rating is already a published minimum from a test population, so a further factor double counts.", "That collapse is less consequential than burst.", "That the collapse formulas are exact rather than empirical, so there is no scatter for a design factor to protect against.", "That the collapse load is a hydrostatic column, which is known more precisely than any of the other three loads in the suite."]'::jsonb, 0, 'It also means there is no margin: a safety factor of 1.05 passes with five percent to a flattened casing.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 4, 'Where does the fluid level sit in the published partial evacuation case?', '["At forty percent of the shoe depth from surface.", "At the top of the lower section, by construction, since the evacuation fraction is chosen to make the two coincide exactly.", "At 1504.7518195805999 m, which is below the section break rather than above it.", "At 1003.1678797204 m, which is the depth an evacuation fraction of 0.4 puts it at on a shoe of 2507.919699301 m."]'::jsonb, 2, 'The level is the shoe depth times one less the evacuation fraction.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 5, 'Section 1 gives the same collapse safety factor on the full and partial evacuation cases. Why?', '["Because the difference falls inside the reporting precision.", "Because the section lies entirely above the fluid level, so both cases give it identical pressure arrays.", "Because the partial evacuation case defaults to the full one whenever the level falls below the first section boundary.", "Because the collapse rating rather than the load is what governs there, and the rating does not depend on the case at all."]'::jsonb, 1, 'It is not an approximation. The two profiles are the same numbers, byte for byte.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 6, 'What is the trap in dropping the full evacuation case from the suite?', '["Section 2''s collapse safety factor jumps from 1.2882443095792595 to 1.8929304140756467 and the string looks safer.", "Nothing, since partial evacuation is more realistic.", "The upper section loses its governing case, since it is the only case in the suite that produces a collapse load there at all.", "The regime reported for the lower section changes from plastic to transition, which changes the advice about how to fix it."]'::jsonb, 0, 'Section 1 is unaffected, which is exactly why the mistake is easy to make.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 7, 'During a cement job, what is inside the casing and what is outside?', '["Wet cement inside and mud outside, before displacement.", "Spacer inside and a lead slurry outside, with the tail slurry confined to the annulus opposite the shoe track only.", "Displacement water inside at 1030 kg/m3 and wet cement outside at 1900 kg/m3, giving a differential that grows with depth.", "Displacement water inside and wet cement outside, which is much the denser of the two."]'::jsonb, 3, 'The differential gradient is 8531.785499999998 Pa per metre.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 8, 'Why keep the cementing case even though it is milder than full evacuation?', '["Because it is the only case that loads the shoe track.", "Because it is the only collapse case in which the internal column is not zero, which makes it the test of the combined check.", "Because it certainly happens, the densities can be worse, and a joint damaged then carries the damage through every later case.", "Because the cement sets and the case therefore becomes permanent, unlike the transient loads the other six represent."]'::jsonb, 2, 'Full evacuation is a hypothesis. The cement job definitely happens.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 9, 'What does the cementing case in this engine leave out?', '["The density of the displacement fluid inside the pipe.", "Friction pressures, surge and swab from pipe movement, a partial cement column and the gelation window.", "The axial load, since the string is landed and cemented by then and the hanging weight is transferred to the wellhead.", "The collapse regime, since the pipe is supported by the setting cement and no free-pipe collapse formula applies to it."]'::jsonb, 1, 'It is a screening version of the case, and the Cementing course computes the real one.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 10, 'What collapse regime does the published string report on every case and section?', '["Plastic, because both 9-5/8 inch sections sit inside their own plastic band at their own grades.", "Elastic, as most casing does under external pressure.", "Transition on the upper section and plastic on the lower one, because the two sections carry different grades of steel.", "It varies with depth inside each section, and the engine reports the regime that occurs at the greatest number of grid points."]'::jsonb, 0, 'The axial derating at these tensions is not enough to move either of them out.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 11, 'Why report a collapse regime at all if it is uniform on this string?', '["Because the design factor depends on the regime.", "Because the regime is what selects the formula, so reporting it lets a reader reproduce the collapse rating independently.", "Because the moment it is not uniform, the advice for the two sections becomes different.", "Because a change of regime within a section indicates that the axial profile has crossed the yield strength somewhere in it."]'::jsonb, 2, 'A three-section string with a 13-3/8 inch tieback would report elastic there and plastic below.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 12, 'Which reported collapse regime should alarm you?', '["Elastic, because the grade then buys nothing.", "Transition, because it is the least well characterised of the four published fits and carries the widest scatter of test data.", "Yield, because a pipe thick enough to collapse by yielding is heavier and more expensive than the design probably needed.", "Yield-exhausted, because it means the axial stress reached the yield strength and the collapse rating there is zero."]'::jsonb, 3, 'The collapse number is then a symptom and the disease is axial.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 13, 'Where in the collapse loop does combined loading enter?', '["Once per section, at the section''s governing depth.", "At every depth, because the collapse rating is recomputed there from the axial stress at that depth.", "Once per case, using the maximum axial force anywhere in the string, which is the most conservative single choice available.", "Nowhere, because the derating is applied to the rating in the tier below and the load case evaluation uses the derated value."]'::jsonb, 1, 'There is no single collapse rating for a section under this check.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 14, 'Why does the engine write the axial stress as a maximum against zero?', '["Because API does not credit compression, so a section in compression keeps its undegraded collapse rating.", "Because a negative force would break the square root.", "Because compression and tension have the same effect on collapse, so the sign can be discarded without loss of accuracy.", "Because the axial profile is defined as the buoyed weight below each depth, which cannot be negative on a hanging string."]'::jsonb, 0, 'It makes the conservative choice visible in one character.'),
  ('casingtubing', 'intermediate', 'module', 'm03-the-collapse-cases', 15, 'At the bottom of the deepest section, how much does the derating contribute to the collapse answer?', '["Everything, because the collapse load is largest there.", "About a fifth, which is the derating a 9-5/8 inch section carries at the axial stress the buoyed string produces at that depth.", "Nothing, because the axial force there is zero by construction and the rating is the undegraded one.", "It depends on the case, because the buoyancy factor changes with the fluid the string is immersed in for each one."]'::jsonb, 2, 'On a single-section string the collapse check and the derating never meet at the governing depth.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 1, 'How does the engine build the axial profile?', '["From the string weight and the measured depth along the hole.", "Weight per metre times the buoyancy factor times the length hanging below, plus any overpull at surface.", "By integrating the buoyed weight of each section separately, so that a tapered string carries its own weight per section.", "From the difference between the internal and external pressure columns acting on the steel cross-section at each depth."]'::jsonb, 1, 'Linear in depth, largest at surface, and zero at the shoe unless there is an overpull.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 2, 'The buoyancy factor is one less the mud density over 7850. Where does that come from?', '["Archimedes: the displaced volume is the steel volume, so the fraction of weight lost is the ratio of the two densities.", "An empirical correlation for casing in drilling mud.", "The ratio of the steel area to the total area enclosed by the outside diameter, which is what the fluid actually displaces.", "The definition of apparent weight, which is the true weight scaled by the ratio of the fluid pressure to the yield strength."]'::jsonb, 0, 'It is exact only for a pipe that is open and full of the same fluid inside and out.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 3, 'At a mud weight of 1440 kg/m3, what fraction of the string''s air weight does the fluid carry?', '["About half, because steel is roughly twice as dense as mud.", "None, because the mud is inside the string as well as outside it and the two contributions cancel exactly on an open pipe.", "About eighteen percent, since the buoyancy factor comes to 0.8165605095541402.", "About eight percent, which is the ratio of the mud density to the density of steel expressed as a percentage figure."]'::jsonb, 2, 'The hook feels the rest, which on this string is 1492077.9549772663 N at surface.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 4, 'Where is the buoyed axial profile used and where is it not?', '["In all four checks, since it is a load like any other.", "In the tension and triaxial checks only, since those are the two that read a force rather than a pressure differential.", "In the tension check, the collapse derating and the triaxial check, and not in burst, which reads pressures alone.", "In the tension check and inside the collapse derating, and not in burst or in either pressure column."]'::jsonb, 3, 'The pressure columns are set by fluid heads and have nothing to do with what the steel weighs.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 5, 'The engine takes one weight per metre for the whole string. What does that approximate?', '["Nothing, because the published string has one section.", "A tapered string whose sections have different weights, here 69.9437033 and 79.61676865 kg per metre.", "The added weight of the couplings, which the nominal weight excludes and which the adjusted weight in the catalog includes.", "The buoyed weight, since the single figure supplied is already reduced by the buoyancy factor before it reaches the profile."]'::jsonb, 1, 'The published run uses 74.296582707, which is between the two.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 6, 'What does overpull do to the axial profile?', '["It adds a constant force at every depth, because a tension applied at one end is carried by the whole bar.", "It adds a force at surface that decays with depth.", "It scales the whole profile up by the ratio of the applied pull to the hanging weight, preserving the shape of the curve.", "It adds a force below the point at which the string is stuck, since above that point the hanging weight is unchanged."]'::jsonb, 0, 'The published run uses 445000 N, about a hundred thousand pounds force.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 7, 'Which cases does the engine apply the overpull to?', '["All seven, since the environment object is shared.", "The three burst cases, because those are the ones performed with the string still hung off in the slips at the rotary table.", "The running case only, because the other six describe a string that is landed and cemented.", "None of them, because overpull is a rig operation rather than a design load and is reported separately from the seven cases."]'::jsonb, 2, 'A reader who changes it and sees six cases unmoved has not found a bug.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 8, 'Overpull costs section 1 about 23 percent of its tension margin and section 2 about 43. Why more on the lower one?', '["Because its connection efficiency is lower.", "Because it has less weight hanging below it, so a fixed 445000 N is a larger fraction of its total load.", "Because the buoyancy factor is applied only to the hanging weight, so the overpull is proportionally larger in the buoyed profile.", "Because its pipe body yield is smaller, which makes the same absolute force a larger fraction of the section''s capacity."]'::jsonb, 1, 'An overpull hurts the bottom of a string proportionally more than the top.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 9, 'Why is the tension design factor the largest of the four?', '["Because the pipe body yield is the least certain rating.", "Because the axial profile carries the largest modelling error of the four loads, given that one weight per metre is assumed.", "Because parting a string is unrecoverable, and because the real running load contains shock and drag that none of this captures.", "Because parting a string is qualitatively worse than yielding one, and running adds shock, drag and slip crushing."]'::jsonb, 3, 'It is 1.6 against 1.1 for burst, 1.25 for triaxial and 1.0 for collapse.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 10, 'What does the Lame solution give that Barlow does not?', '["The axial stress at the bore and outside surface.", "The exact internal yield pressure, which Barlow approximates by assuming a uniform hoop stress across a thin wall section.", "The hoop and radial stresses as functions of radius, so the variation across the wall is carried rather than averaged.", "The combined effect of internal and external pressure, which Barlow treats as a single differential rather than separately."]'::jsonb, 2, 'It is exact for a thick walled cylinder in plane strain.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 11, 'Why do both pressures matter separately in the Lame formulas?', '["Because each appears in more than one combination, and only the term in one over radius squared depends on the difference alone.", "Because the radial stress equals the local pressure.", "Because the hoop stress uses the inside pressure and the radial stress uses the outside one, so they cannot be combined.", "Because the axial stress is computed from the difference of the two pressures acting on the end area of the section."]'::jsonb, 0, 'Burst and collapse throw that information away. Triaxial does not.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 12, 'At which radii does the engine evaluate the wall stresses?', '["At the mean radius, which is the standard simplification.", "At the bore and at the outside surface, taking the worse of the two rather than a midpoint.", "At ten points across the wall, so that the worst point can be located rather than assumed to lie at one of the two surfaces.", "At the bore only, since the hoop stress is always highest there for any combination of internal and external pressure."]'::jsonb, 1, 'Both are candidates, because the sign of the outside stress can flip when the external pressure dominates.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 13, 'Under pure axial tension with no pressure, what does the von Mises equivalent reduce to?', '["The axial stress itself, so the triaxial safety factor becomes the tension safety factor exactly.", "Zero, since there is no differential stress state.", "The square root of three halves times the axial stress, which is the usual factor for a uniaxial state under this criterion.", "Half the axial stress, because the hoop and radial terms each contribute a quarter of the sum inside the square root."]'::jsonb, 0, 'The engine''s own test asserts it, and an implementation that fails it is wrong.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 14, 'How does the engine handle the bending stress from a dogleg?', '["It adds it to the axial stress and moves on.", "It resolves the bending into the hoop and radial components using the local curvature, then adds all three before combining.", "It evaluates the von Mises expression with the bending stress added and again with it subtracted, and takes the worse.", "It applies it only where the axial force is positive, since a string in compression does not carry a bending stress at all."]'::jsonb, 2, 'Which side of the pipe is worse depends on the sign of the axial force and on the pressures.'),
  ('casingtubing', 'intermediate', 'module', 'm04-axial-and-triaxial', 15, 'The evaluation tracks four minima independently. Why must they be separate?', '["Because the four checks use different design factors.", "Because the burst and collapse checks are skipped at depths where their differential is negative, so their sample sets differ.", "Because tension peaks at the top and collapse at the bottom, and burst can do either depending on which case is running.", "Because the four loads peak in different places, so the four reported numbers can come from four different depths."]'::jsonb, 3, 'Only two of the four report a depth, which is an asymmetry worth noticing.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 1, 'Why do the four checks carry four different design factors?', '["Because API publishes a different factor for each.", "Because each encodes a different amount of trust in the rating it is applied to, and in the consequence of exceeding it.", "Because the four loads are computed to different precisions, and the factor is chosen to cover the numerical error in each.", "Because the four checks are performed at different depths, and a factor applied deeper has to cover more uncertainty."]'::jsonb, 1, 'Collapse gets 1.0 and tension gets 1.6, and the reasons are different in kind rather than in degree.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 2, 'What produces a FAIL verdict on a section?', '["Any one of the four safety factors falling below its own design factor.", "Two or more of the four falling below their factors.", "The lowest of the four falling below the smallest design factor in the set, which is the collapse factor of exactly one.", "Any one of the four falling below 1.0, since a safety factor below unity is what a failure means in every published scheme."]'::jsonb, 0, 'It is a per section per case verdict, and there is no overall string verdict at all.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 3, 'What are the three warning thresholds on the published design factor set?', '["All four checks at 1.1 times their design factors.", "Burst below 1.21, collapse below 1.1, tension below 1.76 and triaxial below 1.375, which is 1.1 times each of the four.", "Burst below 1.21, collapse below 1.1 and triaxial below 1.375, being 1.1 times each of those three factors and none for tension.", "Burst below 1.2100000000000002, collapse below 1.1 and triaxial below 1.375."]'::jsonb, 3, 'Tension is absent from the warning rule, which is a choice and not an oversight.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 4, 'Is leaving tension out of the warning band defensible?', '["No, because every check needs a warning band.", "Yes, because the tension check is exact rather than empirical, so there is no scatter for a warning band to protect against.", "Yes, because tension already carries the largest design factor and a further ten percent would flag sections that are fine.", "No, because tension is the check whose consequence is worst, which is precisely why it should carry the widest warning band."]'::jsonb, 2, 'It is a choice, and it is written nowhere except in the code.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 5, 'What is a WARNING verdict asking the reader to do?', '["Change the pipe in that section before proceeding.", "Look, and specifically at whether the assumption behind the load is as conservative as it should be.", "Recompute the section at a finer grid spacing, since a warning usually indicates that the governing depth has been missed.", "Apply a larger design factor to the check that produced it, since the margin has been shown to be smaller than assumed."]'::jsonb, 1, 'A section at a burst safety factor of 1.21 has its whole margin resting on the load case being right.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 6, 'How many of the fourteen published section evaluations are not a PASS?', '["Exactly one, and it is a WARNING rather than a FAIL.", "Two, both of them on the deeper section.", "Three, one on each of the burst cases and one on the deepest collapse case, all of them warnings rather than failures.", "None, because the published string was chosen so that every check clears its design factor with margin to spare."]'::jsonb, 0, 'Thirteen pass, one warns, none fails.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 7, 'Which case and section produce the one WARNING?', '["The gas kick on section 1, at the wellhead.", "The full evacuation case on section 2, which reports the lowest collapse safety factor anywhere in the seven case suite.", "The pressure test on section 2, at the shoe, where the internal column is highest.", "The running case on section 1, where the overpull brings the tension safety factor closest to its design factor of 1.6."]'::jsonb, 2, 'Its four numbers are burst 1.2123376873879477, no collapse, tension 7.879089408631784 and triaxial 1.3684762565196722.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 8, 'Which check actually produced that WARNING?', '["The burst one, at 1.2123376873879477 against 1.21.", "The triaxial one, at 1.3684762565196722 against a warning threshold of 1.375.", "The collapse one, since the case produces no collapse differential and a null is treated as below the warning threshold.", "Both burst and triaxial together, since each of them falls inside its own warning band on that section and that case."]'::jsonb, 1, 'The case is named after burst, and burst clears its own threshold.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 9, 'Why does it matter that the WARNING came from triaxial rather than burst?', '["It does not matter, since the verdict is the same either way.", "Because the burst rating cannot be raised on that section without changing the grade, while the triaxial number can be improved.", "Because the triaxial number is low from three things acting at once, and only one of them is a property of the pipe.", "Because the fix the burst column suggests would work by accident rather than by addressing what is actually low."]'::jsonb, 3, 'Take the dogleg out and the triaxial number rises with no change to the pipe at all.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 10, 'By how much did the burst number clear its own warning threshold?', '["By about ten percent, the width of the warning band.", "By 0.1123376873879477, which is the difference between the burst safety factor and the burst design factor of 1.1.", "By 0.0023376873879474847, which is about a fifth of a percent.", "By nothing measurable, since both numbers round to 1.21 at the precision a design report would normally quote them to."]'::jsonb, 2, 'The conclusion that triaxial is the binding check rests entirely on those two thousandths.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 11, 'Raising the test pressure from 35000000 Pa to 35100000 does what to the diagnosis?', '["Both checks then flag, the verdict is unchanged, and the statement about which one is binding stops being true.", "Nothing, because the change is inside the tolerance.", "The verdict becomes a FAIL, because the burst safety factor then falls below the burst design factor rather than the band.", "The triaxial number rises while the burst one falls, because the two respond to the internal pressure in opposite directions."]'::jsonb, 0, 'Any conclusion of the form X is the reason and Y is not is only as strong as the gap between them.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 12, 'Which perturbation would confirm that the bending term was carrying the triaxial result?', '["Raising the test pressure, which moves both together.", "Taking the dogleg to zero, since the triaxial number rises and the burst number does not move at all.", "Changing the grade of the section, since that raises the burst rating and the yield strength the triaxial number is divided by.", "Reducing the mud weight, since that lowers the internal column and therefore both the burst and the triaxial differentials."]'::jsonb, 1, 'Two perturbations tell you which finding is about the string and which is about the numbers.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 13, 'Which of these does the string check NOT cover?', '["The combined effect of tension on the collapse rating.", "The bending stress from a dogleg, which is applied to the axial stress in the triaxial check but nowhere else in the suite.", "The variation of the load along a section, which is exactly what the whole-profile scan was introduced in order to capture.", "Wear, temperature derating, cement support, ovality, buckling, connection sealing and fatigue."]'::jsonb, 3, 'Every one of those seven would move at least one number in the unsafe direction.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 14, 'Why does ignoring cement support make the collapse check conservative?', '["Because cement adds weight to the outside of the pipe.", "Because the cement column is denser than mud, so a check that assumed mud outside would understate the collapse load itself.", "Because a cemented casing is restrained by what surrounds it, so its real capacity exceeds the free-pipe rating.", "Because good cement removes the external pressure entirely, leaving only the formation stress acting on the outside of the pipe."]'::jsonb, 2, 'Sometimes very conservative, and this check takes the free-pipe number anyway.'),
  ('casingtubing', 'intermediate', 'module', 'm05-reading-a-string-check', 15, 'Why list the omissions before the capstone rather than after it?', '["Because a learner who can produce six correct safety factors and cannot say what they exclude has learned the arithmetic only.", "Because the capstone grades the omissions directly.", "Because the omissions change the numerical answers, so a learner who does not know them will compute the six fields wrongly.", "Because the list is long enough that it needs to be studied separately from the calculation it qualifies, and before it."]'::jsonb, 0, 'That is the difference between the arithmetic and the engineering.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Summarising the Professional tier: why do seven load cases exist?', '["Because API requires seven for a casing design.", "Because no single one of them is worst everywhere, on any section or on any of the four checks.", "Because each of the seven corresponds to one stage of the well''s life, from running the string through to abandoning it.", "Because the four checks each need at least one case built to load them, and three of the checks need two cases apiece."]'::jsonb, 1, 'And the whole-profile scan exists because no single depth is worst either.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'A capstone changes the mud weight, the shoe depth and both grades. What stays the same?', '["The method: seven cases, two columns each, a scan inside every section and four safety factors out.", "Nothing, since every input to every formula has moved.", "The governing depths, since those are set by the ordering of the fluid gradients rather than by their absolute values.", "The collapse regimes, since the pipes are still 9-5/8 inch and the regime depends on the ratio of diameter to wall alone."]'::jsonb, 0, 'Nothing about the procedure depends on the numbers it is given.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A capstone shoe of 2200 m over 50 intervals gives what grid spacing?', '["Fifty metres, as with the published run.", "Forty four metres, which happens to place a grid point exactly on the break at 1200 m and simplifies the section assignment.", "It depends on the section break, since the engine subdivides each section separately into an equal number of intervals.", "Forty four metres exactly, so the section break at 1200 m falls between two grid points."]'::jsonb, 3, 'The last point in the upper section is 1188 m and the first in the lower one is 1232.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'An evacuation fraction of 0.7 on a 2200 m shoe puts the level where?', '["At 1540 m, which is below the section break.", "At 660 m, which is above the break at 1200 m, so the identity between the two evacuation cases no longer holds on either section.", "At 660 m, which is inside the upper section rather than below it.", "At the section break itself, by construction, since the fraction is chosen to make the two coincide for the capstone run."]'::jsonb, 2, 'So the two evacuation cases differ on both sections rather than on one.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Why is assuming the two evacuation cases agree on the upper section a capstone trap?', '["Because the two cases never agree on any section.", "Because that identity held only because the published level fell below the break, and the capstone level does not.", "Because the identity holds for the collapse check and not for the triaxial one, which sees the internal pressure separately.", "Because the partial case uses a packer fluid of 1200 rather than 1150, so the numbers differ even above the fluid level."]'::jsonb, 1, 'It is the right identity remembered from the wrong string.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A capstone dogleg of 3.5 degrees per 30 m against the lessons'' 2 does what to the bending term?', '["Raises it by 75 percent, because the bending stress is linear in the curvature.", "Leaves it unchanged, since the pipe size is the same.", "Raises it by about a third, since the bending stress goes as the square root of the curvature for a pipe of fixed diameter.", "Raises it by 75 percent and raises the axial stress by the same amount, since both are computed from the same curvature."]'::jsonb, 0, 'It affects the triaxial number and nothing else in the report.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'A capstone applies 620000 N of overpull on a shorter, lighter string. Where does it hurt most?', '["On the upper section, which carries the most total load.", "Equally on both, because a tension applied at surface is carried by the whole bar and adds the same force at every depth.", "On the lower section, since the overpull is a larger fraction of its total axial load than of the upper section''s.", "On the lower section, because there is less weight hanging below it for the fixed pull to be compared against."]'::jsonb, 3, 'The force added is the same everywhere and the base it is added to is not.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'On a capstone with a gas gradient of 1900 and a seawater backup of 1025, where does the kick govern?', '["At the shoe, because the gas gradient has been reduced.", "At zero metres, because 1900 is still far below the seawater gradient of 10051.81625.", "At the section break, because the two columns cross there once the lighter gas gradient is applied to the internal column.", "It cannot be said without running the case, because the ordering depends on the shoe pressure as well as on the gradients."]'::jsonb, 1, 'The sign of the slope is what decides it, and reducing the gas gradient makes the slope more negative rather than less.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'A capstone connection on the lower section is short thread. Which field does that hit?', '["The burst safety factor, through the rating.", "The collapse safety factor, because the derating from tension is applied against the joint strength rather than the body yield.", "The tension safety factor, since the joint strength is the pipe body yield times 0.75.", "The triaxial safety factor, since the von Mises equivalent is compared against the connection''s yield rather than the pipe''s."]'::jsonb, 2, 'Buttress would give the same section a third more tension capacity.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'If one of six capstone safety factors is far smaller than the rest, what should you conclude?', '["That the string has a specific problem in a specific place, and that number is telling you where.", "That the calculation for that field went wrong.", "That the design factors are inconsistent, since a well proportioned string should show similar margins across all four checks.", "That the case producing it is unrealistic, since a real string would not be run with one check so far below the others."]'::jsonb, 0, 'A verdict per section per case exists precisely so that the answer is a location and not a word.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Before submitting a string capstone, what should you be able to say without checking?', '["The exact value of every one of the fourteen verdicts.", "The governing depth for each of the four checks on both sections, since only two of the four are reported by the engine.", "Which case and section produce the worst verdict, and by how much each of the four safety factors misses its design factor.", "Which case and which section produce the one non-passing verdict among the fourteen."]'::jsonb, 3, 'Otherwise you have computed six numbers rather than checked a string.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A free check on a burst answer says it should govern at exactly zero metres. What is it testing?', '["That the grid spacing was computed from the right shoe.", "That the section assignment was correct, since the wellhead belongs to the upper section and must not be tested against the lower.", "That the sign of the differential slope was taken correctly, since a lighter inside column governs at the top.", "That the burst rating was computed on the minimum wall, since a nominal-wall rating would shift the governing depth downward."]'::jsonb, 2, 'If the answer came from anywhere else, the two gradients were compared the wrong way round.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A Professional certificate in this course stands for which competence?', '["Select the casing scheme for a well from first principles.", "Check a string against its service loads and say which check, which section and which depth produced each verdict.", "Predict the pressure at which a given string will actually fail, including the effects of wear and temperature on the ratings.", "Produce the four ratings for any joint in the catalog at any grade, which is the capacity half of a casing design."]'::jsonb, 1, 'The capacity half was the tier below, and the two together are a design.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Every case in this tier is a drilling or test case. What is missing?', '["Anything that happens after the well is completed, which is where the tubing and the packer come in.", "The cement job, which happens before the string is run.", "The abandonment loads, which are the last thing a string sees and are covered in the Well Integrity and P and A course.", "The production casing burst case, since the gas kick represents a drilling influx rather than a produced fluid at full pressure."]'::jsonb, 0, 'A tubing string moves, and a cemented casing cannot.'),
  ('casingtubing', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What is the transferable habit from the two thousandths result?', '["Always quote safety factors to seven decimal places.", "Treat any verdict that depends on a comparison between two checks as unreliable, since the ordering can change with any input.", "Compute the gap whenever a report says one check is binding, and perturb the input that would change it.", "Recompute the whole suite whenever a single input changes, since the ordering between the four checks is not stable."]'::jsonb, 2, 'The finding was true, and it was two thousandths deep, and knowing both is the skill.'),
  ('casingtubing', 'intermediate', 'final', null, 1, 'You are handed a pressure profile and asked whether the string is safe. What else do you need?', '["Only the design factors, since the ratings follow.", "The ratings, the section list and a design factor set, because a load with no capacity is half a design.", "The trajectory, since the true vertical depths are already in the profile and the measured depths add nothing to the check.", "The mud weight, which sets both the collapse load and the buoyancy factor and is therefore the only other input required."]'::jsonb, 1, 'The tier below supplied the capacities and this one supplies the loads.'),
  ('casingtubing', 'intermediate', 'final', null, 2, 'A pressure profile is supplied on measured depth. What is wrong with it?', '["Hydrostatic pressure depends on vertical height, so a measured depth column overstates every head on a deviated well.", "Nothing, provided the well is close to vertical.", "The axial profile would be wrong instead, since the weight hanging below a point depends on the length of pipe rather than height.", "The grid spacing would be uneven, since the engine builds a uniform grid in true vertical depth from the shoe depth given."]'::jsonb, 0, 'The measured depth matters for how much steel is hanging, and the engine takes the weight as an input.'),
  ('casingtubing', 'intermediate', 'final', null, 3, 'Two columns of the same density, inside and out. What does the check report?', '["Zero for both, since there is no capacity mobilised.", "A burst safety factor computed on a differential of zero, which is reported as the largest finite number the engine can hold.", "No burst or collapse numbers at all, and only the tension and triaxial checks, because neither differential is ever positive.", "Infinite burst and collapse safety factors, with null governing depths on both."]'::jsonb, 3, 'That is the running case, and what it has instead is the full buoyed weight plus overpull.'),
  ('casingtubing', 'intermediate', 'final', null, 4, 'A case has gas inside and water outside. Where is the burst worst?', '["At the deepest point, as with any pressure load.", "At the point where the two columns are closest together, since that is where the differential passes through its minimum.", "At the shallowest point, because the inside column loses almost nothing while the outside one loses everything.", "At the casing shoe, because the gas pressure there is set by the fracture gradient and is the highest pressure in the case."]'::jsonb, 2, 'It is the exception to the rule that everything about a well gets worse with depth.'),
  ('casingtubing', 'intermediate', 'final', null, 5, 'Pumping up on a mud filled string that has water behind it: which end takes the most differential?', '["At surface, where the applied pressure is greatest.", "At the deepest point, because mud outweighs water and the differential grows downward.", "At the point where the mud column has grown enough to overcome the surface pressure, which is inside the upper section.", "It depends on the surface pressure, since a large enough one makes the differential largest at the wellhead instead."]'::jsonb, 1, 'The slope is the difference of two liquid gradients, so it is gentle and positive.'),
  ('casingtubing', 'intermediate', 'final', null, 6, 'Which comparison decides the governing end of a section for burst?', '["The inside gradient against the outside gradient, and nothing else about the case enters it.", "The inside pressure at surface against the rating.", "The design factor against the safety factor, since the governing end is defined as the one where the margin is smallest.", "The section length against the grid spacing, since a section shorter than one interval has only a single candidate point."]'::jsonb, 0, 'Most people never write that comparison down, and getting it wrong produces a comfortable number rather than an error.'),
  ('casingtubing', 'intermediate', 'final', null, 7, 'You evaluate a section at its shoe only. On which kind of case does that overstate the margin?', '["Any case with a liquid inside and a liquid outside.", "Every case, since the section shoe is never a grid point and the check therefore samples the wrong depth on all of them.", "Only the collapse cases, since the collapse differential is the one that grows with depth on every case in the suite.", "Any case whose differential shrinks with depth, which on this suite is the gas kick and the custom gradient."]'::jsonb, 3, 'On the published gas kick it overstates section 1 by 41.8 percent.'),
  ('casingtubing', 'intermediate', 'final', null, 8, 'What would a shoe-only check have reported on the published gas kick, section 1?', '["The same number, because the section shoe governs.", "1.6904923854809817 against a true 2.396900745393525, since scanning finds a higher rather than a lower safety factor.", "2.396900745393525 against a true 1.6904923854809817, both against a design factor of 1.1.", "A null, because the burst differential at the section shoe on that case is negative and the check therefore skips it."]'::jsonb, 2, 'Both pass on this string, and at K-55 one would pass and the other would not.'),
  ('casingtubing', 'intermediate', 'final', null, 9, 'Why does a bug of that kind survive in a tool?', '["Because nobody checks the burst cases carefully.", "Because it never errors and never produces an implausible number, only a slightly optimistic one on one case.", "Because it produces a conservative answer, and a conservative error in a design tool is rarely investigated by its users.", "Because the error only appears on strings with more than one section, and most screening runs use a single uniform string."]'::jsonb, 1, 'The only way to notice is to know in advance which end should have governed.'),
  ('casingtubing', 'intermediate', 'final', null, 10, 'A collapse differential equals the mud hydrostatic exactly. Which case is running?', '["Full evacuation, because the inside pressure is zero at every depth.", "Cementing, with water inside and cement outside.", "Partial evacuation above the fluid level, where the inside pressure is zero and the outside column is the full mud head.", "The custom gradient case with the internal density set to zero, which is how the engine implements the evacuation cases."]'::jsonb, 0, 'At the published shoe that is 35415778.63557866 Pa.'),
  ('casingtubing', 'intermediate', 'final', null, 11, 'Two collapse cases give byte-identical numbers on one section. What does that tell you?', '["That one of the two cases was not actually run.", "That the section''s collapse rating governs rather than the load, so the reported safety factor is a property of the pipe alone.", "That the two cases share an internal column above the fluid level and differ only in the density below it.", "That the two profiles are the same arrays there, so the difference between the cases happens somewhere else."]'::jsonb, 3, 'It is not an approximation, and dropping one of the two would lose the other section''s governing case.'),
  ('casingtubing', 'intermediate', 'final', null, 12, 'Why is the cementing collapse case milder than a full evacuation on this string?', '["Because the cement supports the pipe as it sets.", "Because the cement column reaches only to the top of the annulus rather than to surface, so the head is smaller at every depth.", "Because its differential gradient is the cement less the water, 8531.785499999998, against the full mud head.", "Because the design factor for a transient load is relaxed, and the cement job lasts only a few hours out of the well''s life."]'::jsonb, 2, 'Milder by roughly the ratio of the two differential gradients.'),
  ('casingtubing', 'intermediate', 'final', null, 13, 'Which collapse case certainly happens on every well?', '["The full evacuation, which is the design basis.", "The cement job, which every joint in the string experiences, unlike an evacuation which is a hypothesis.", "The partial evacuation, since a completion fluid level always falls to some degree once the well is put on production.", "None of them, because a well that is drilled and completed without incident may never see a net external pressure at all."]'::jsonb, 1, 'A joint damaged during cementing carries that damage through every later case.'),
  ('casingtubing', 'intermediate', 'final', null, 14, 'The published string reports the plastic collapse regime everywhere. What would change that?', '["A section of a different size, such as a 13-3/8 inch tieback, which would report elastic instead.", "A heavier mud weight, which raises the collapse load.", "A deeper shoe, since the axial derating grows with the hanging weight and eventually pushes the pipe into the yield regime.", "A different load case, since the regime is recomputed for each case from the pressures acting at the governing depth."]'::jsonb, 0, 'And the advice for the two sections would then be different.'),
  ('casingtubing', 'intermediate', 'final', null, 15, 'Where does the collapse derating contribute nothing on a single-section string?', '["At the top, where the tension is largest.", "Everywhere, because the derating applies to the rating and the load case evaluation compares against the undegraded value.", "At the deepest point, since the axial force there is zero and the collapse rating used is therefore the undegraded one.", "At the governing depth, because that is the deepest point and nothing hangs below it."]'::jsonb, 3, 'It is only on a tapered string, where a section''s bottom still has string below it, that the two interact.'),
  ('casingtubing', 'intermediate', 'final', null, 16, 'The buoyancy factor at 1900 kg/m3 mud is smaller than at 1030. What does that do to the hook load?', '["Raises it, because the heavier mud adds weight.", "Reduces it, because a denser fluid carries more of the string''s weight.", "Leaves it unchanged, since the mud is inside the pipe as well as outside it and the two contributions cancel exactly.", "Reduces the load at the top and raises it at the bottom, because the buoyancy acts on the displaced volume at each depth."]'::jsonb, 1, 'It also improves the tension safety factor, which is one of the few things heavy mud makes better.'),
  ('casingtubing', 'intermediate', 'final', null, 17, 'An overpull of 445000 N is applied. Where in the string is the force increased?', '["Everywhere, by the same amount, because an axial load applied at one end is carried by the whole bar.", "Only above the point where the string is stuck.", "At surface only, since the overpull is a hook load rather than a force in the steel and dissipates into the hanging weight.", "In proportion to depth, since the pull is distributed along the string by the friction between it and the borehole wall."]'::jsonb, 0, 'Which is why it hurts the bottom of the string proportionally more.'),
  ('casingtubing', 'intermediate', 'final', null, 18, 'Which two of the four minima does the engine report a depth for?', '["Tension and triaxial, since those are forces.", "All four, since the loop tracks each minimum independently and records the depth at which each of them was found to occur.", "Burst and collapse, leaving tension and triaxial as bare numbers.", "Collapse and triaxial, since those are the two whose ratings vary with depth and therefore need a location to be reproducible."]'::jsonb, 2, 'If a triaxial verdict is the one that fails, you have to find where yourself.'),
  ('casingtubing', 'intermediate', 'final', null, 19, 'Why search the profile rather than argue where the extreme is?', '["Because searching is faster than reasoning.", "Because the argument only works while the profiles are simple, and a real string is not.", "Because the argument requires knowing the ratings in advance, and the ratings depend on the axial load which varies with depth.", "Because the grid is uniform, so a search over fifty one points is exhaustive while an analytic argument is not."]'::jsonb, 1, 'An engine that searches is right on both. An engine that argues is right on the easy one.'),
  ('casingtubing', 'intermediate', 'final', null, 20, 'What does a null triaxial safety factor mean in a section report?', '["That the case produced no differential pressure at all.", "That the section lies outside the depth range the profile covers, so no grid point fell inside it to be evaluated.", "That the von Mises equivalent came out at zero, which happens on any case with no pressure and no axial force at all.", "It does not occur, because the triaxial check is evaluated at every depth regardless of the pressure signs."]'::jsonb, 3, 'Burst and collapse can be null. Triaxial and tension have no positivity test to fail.'),
  ('casingtubing', 'intermediate', 'final', null, 21, 'Which of the four checks sees all three principal stresses?', '["The collapse one, through the combined loading term.", "The burst one, since the Barlow rating already accounts for the axial and radial stresses through the wall tolerance factor.", "The triaxial one, which is why it can bind on a case named after something else.", "The tension one, because the axial force is compared against a body yield computed from the full three dimensional section."]'::jsonb, 2, 'It is also the only check that needs the two pressures separately rather than their difference.'),
  ('casingtubing', 'intermediate', 'final', null, 22, 'A dogleg of 2 degrees per 30 m appears in which of the four checks?', '["The triaxial one only, as a bending stress added to and subtracted from the axial stress.", "All four, since bending affects every rating.", "The tension check as well, since the bending stress adds to the axial force on the outside of the curve and must be included.", "The collapse check, because bending ovalises the pipe and an ovalised pipe collapses at a lower external pressure."]'::jsonb, 0, 'Take it to zero and the triaxial number rises with no change to the pipe.'),
  ('casingtubing', 'intermediate', 'final', null, 23, 'Why does the engine evaluate the bending stress with both signs?', '["Because the dogleg direction is not known.", "Because a positive and a negative bending stress give the same von Mises equivalent, so evaluating both is a consistency check.", "Because the outside of the bend is worse in tension and the inside is worse in compression, and taking the worse removes the need to know which.", "Because which side of the pipe is worse depends on the sign of the axial force and on the pressures."]'::jsonb, 3, 'Taking the maximum removes the need to decide in advance.'),
  ('casingtubing', 'intermediate', 'final', null, 24, 'A section reports burst 1.19, collapse 1.4, tension 1.55, triaxial 2.0. What is its status?', '["WARNING, because burst is inside its warning band.", "FAIL, because burst is below 1.1 is false but tension at 1.55 is below its design factor of 1.6.", "PASS, because every one of the four safety factors is above the corresponding design factor in the published set.", "FAIL, because burst at 1.19 is below the burst warning threshold of 1.21 and a warning threshold breach is a failure."]'::jsonb, 1, 'Tension is the one that fails, and burst at 1.19 would only have produced a warning.'),
  ('casingtubing', 'intermediate', 'final', null, 25, 'Why is there no overall string verdict?', '["Because a string that fails one case in one section has a specific problem in a specific place.", "Because the engine reports per case for performance.", "Because the four checks use different design factors, so there is no consistent way to combine fourteen verdicts into one.", "Because a string verdict would have to be the worst of the fourteen, and the worst is almost always the deepest section."]'::jsonb, 0, 'Collapsing it to a word would lose the only useful information in the report.'),
  ('casingtubing', 'intermediate', 'final', null, 26, 'The one WARNING in the published suite came from a check the case is not named after. What is the general lesson?', '["Cases should be renamed after the check that binds.", "The triaxial check should be given its own case, since it currently only appears as a by-product of the other six cases.", "The name of a case describes what it was built to load rather than what it turns out to load worst.", "A case that produces a verdict from a check other than its own has been mis-specified and should be rebuilt from its intent."]'::jsonb, 2, 'The engine computes all four checks on every case for exactly that reason.'),
  ('casingtubing', 'intermediate', 'final', null, 27, 'How thin was the margin behind the claim that triaxial rather than burst was binding?', '["About ten percent, the width of the warning band.", "0.0023376873879474847 on the burst safety factor, which is about a fifth of a percent.", "About one percent, which is the difference between the two safety factors divided by the smaller of the two.", "It cannot be quantified, because the two checks are compared against different thresholds and are not on a common scale."]'::jsonb, 1, 'Reporting the conclusion without the gap is how a result about one input set becomes a property of the system.'),
  ('casingtubing', 'intermediate', 'final', null, 28, 'Two perturbations distinguish a robust finding from a marginal one. Which two, here?', '["Changing the grade, and changing the mud weight.", "Refining the grid, and moving the section break, since both change which depths the four checks are actually evaluated at.", "Removing the dogleg, which moves triaxial alone, and raising the test pressure, which moves burst and triaxial together.", "Taking the dogleg to zero, and raising the test pressure by a few percent."]'::jsonb, 3, 'One isolates the bending term and the other shows the two are not independent.'),
  ('casingtubing', 'intermediate', 'final', null, 29, 'Which omission would most affect the deepest section of a hot well?', '["Temperature derating of the yield strength, since the deepest section is both the hottest and the closest to its limits.", "Ovality, which is a property of the individual joint.", "Cement support, since a deep section is the best cemented part of the string and the check ignores the restraint entirely.", "Connection sealing, since the highest internal pressure in the suite occurs at the shoe during the pressure test."]'::jsonb, 0, 'Roughly ten percent of yield is lost by 150 degrees for common grades, and nothing here derates for it.'),
  ('casingtubing', 'intermediate', 'final', null, 30, 'Wear is named in both lower tiers. What should really be done about it?', '["Apply a larger design factor to burst and collapse.", "Add a wear allowance to the nominal wall at the design stage, which is what the 12.5 percent tolerance factor already does.", "Recompute every rating on the worn wall, which is what the Torque, Drag and Casing Wear course predicts.", "Inspect the casing before the next section is drilled, since a predicted wear figure is less reliable than a caliper log."]'::jsonb, 2, 'A worn joint has less burst, less collapse and less tension, and none of the ratings here know.'),
  ('casingtubing', 'intermediate', 'final', null, 31, 'What does the Expert tier add that this one does not have?', '["The load cases that happen after completion.", "A string that is allowed to move, and the two limits that follow from that permission.", "A finer treatment of the same seven cases, with a thermal profile and a real trajectory in place of the single dogleg used here.", "The connection ratings that the joint strength efficiency stands in for, taken from the manufacturer data sheets directly."]'::jsonb, 1, 'A cemented casing cannot move. A tubing string can, and it does.'),
  ('casingtubing', 'intermediate', 'final', null, 32, 'Which course provides the shoe pressure the gas kick case is built on?', '["Well Control, through the kick tolerance and the shoe fracture pressure.", "Cementing, which sets what is behind the pipe.", "Geomechanics, which produces the fracture gradient, though the conversion into a shoe control pressure belongs elsewhere.", "Well Design and Surveys, which sets the shoe depth and therefore the pressure the formation there is able to hold."]'::jsonb, 0, 'The fracture gradient itself comes from Geomechanics and the kick argument from Well Control.'),
  ('casingtubing', 'intermediate', 'final', null, 33, 'A capstone string reports one FAIL among fourteen. What is the right first response?', '["Raise the design factor to make the verdict a warning.", "Rerun the whole suite at a finer grid, since a single failure among fourteen often reflects a governing depth that was missed.", "Identify the case, the section and the check that produced it, since the fix depends on all three and not on the verdict.", "Name the case, the section and the check, and then decide what to change about that section."]'::jsonb, 3, 'The verdict is a location, which is the whole point of reporting per section and per case.'),
  ('casingtubing', 'intermediate', 'final', null, 34, 'You reduce a test pressure to fix a burst margin. What else moves?', '["Nothing else, since burst is the only pressure check.", "The collapse number, because reducing the internal pressure increases the net external differential on the same section.", "The triaxial number on the same section, because the internal pressure is one of its three stresses.", "The tension number, since the test pressure acts on the internal cross-section and adds an axial load at the shoe."]'::jsonb, 2, 'That is why the two checks are not independent, and why perturbing one input moves both.'),
  ('casingtubing', 'intermediate', 'final', null, 35, 'Which load case is the only one with a fluid level in it?', '["The gas kick, whose gas column is floored at zero.", "Partial evacuation, whose inside gradient is zero above the level and the packer fluid below it.", "The cementing case, where the top of cement in the annulus is a level of exactly the same kind on the outside of the pipe.", "The custom gradient case, since the surface pressure it applies is equivalent to a level above the wellhead."]'::jsonb, 1, 'It is also the only case whose differential is piecewise linear rather than linear.'),
  ('casingtubing', 'intermediate', 'final', null, 36, 'The published partial evacuation level is 1504.7518195805999 m. What is that a function of?', '["One less the evacuation fraction, times the shoe depth, and nothing else.", "The packer fluid density and the mud density.", "The depth at which the packer fluid column balances the mud column outside, which is where the differential passes zero.", "The section break depth, which the engine uses as the level whenever no evacuation fraction is supplied in the environment."]'::jsonb, 0, 'At 0.4 on a shoe of 2507.919699301 m it lands below the section break, which is what makes the two cases agree above it.'),
  ('casingtubing', 'intermediate', 'final', null, 37, 'Which single number would you check first in a section report you did not produce?', '["The status, since it summarises the other four.", "The lowest of the four safety factors, since that is the one that determines the verdict and therefore the decision.", "The collapse regime, since it decides what advice follows from the collapse number and cannot be inferred from it.", "The governing depth, because it tells you whether the case was understood before any safety factor is read."]'::jsonb, 3, 'A gas kick governing at the shoe is a report to distrust before any of its numbers are read.'),
  ('casingtubing', 'intermediate', 'final', null, 38, 'How does the engine decide whether a grid point belongs to a section?', '["By dividing the depth by the grid spacing and rounding.", "By assigning each grid point to the section whose midpoint it is nearest to, which handles the boundary case unambiguously.", "By comparing the depth against the section''s top and bottom with a nanometre of tolerance at each end.", "By the index, since the section boundaries are chosen to fall on grid points and the assignment is therefore exact."]'::jsonb, 2, 'The tolerance is there so that a boundary point is not lost to floating point.'),
  ('casingtubing', 'intermediate', 'final', null, 39, 'What is a design factor of 1.0 on collapse saying?', '["That collapse failures are recoverable in practice.", "That the rating is already a minimum from a test population, so a further factor would double count the conservatism.", "That the collapse calculation is exact, so no allowance for uncertainty in the rating itself is required by the scheme.", "That the collapse load is known precisely, being a hydrostatic column of a fluid whose density is measured continuously."]'::jsonb, 1, 'It also means a safety factor of 1.05 passes with five percent to a flattened casing.'),
  ('casingtubing', 'intermediate', 'final', null, 40, 'Fourteen evaluations on a two section string. Where does the fourteen come from?', '["Seven cases times two sections, one verdict for each combination.", "Seven cases times four checks, less the nulls.", "Two sections times four checks, plus the six extra evaluations produced by the cases that load more than one check at once.", "Fifty one grid points times two sections, reduced to fourteen by keeping only the governing depth from each combination."]'::jsonb, 0, 'One row per section per case, with four safety factors and a status in each.'),
  ('casingtubing', 'intermediate', 'final', null, 41, 'The custom gradient case in the published run has burst at surface and collapse deeper. Why both?', '["Because the case is run twice with the signs reversed.", "Because the surface pressure of 5000000 Pa is applied to the outside as well as the inside, which reverses the differential.", "Because the two columns cross at a depth inside the upper section, so the differential changes sign partway down it.", "Because its light internal column starts above the external one at surface and falls below it further down."]'::jsonb, 3, 'It is the only case in the suite that produces both checks on the same section.'),
  ('casingtubing', 'intermediate', 'final', null, 42, 'A section spans 0 to 1200 m on a 44 m grid. How many points fall inside it?', '["Twenty seven, since the point at zero is not evaluated.", "Twenty nine, because the boundary at 1200 m is included by the nanometre tolerance the assignment applies at each end.", "Twenty eight, from zero through 1188 m, because 1232 m is already past the section bottom.", "It depends on the case, because the assignment is repeated for each case and the grid is rebuilt from the shoe each time."]'::jsonb, 2, 'The grid is built once from the shoe depth and every case shares it.');
